{
  "packet_id": "H6-T01-1",
  "claim_id": "C003",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C003.component",
    "value": "The reported aggregate does not establish whether the late-start problem is persistent.",
    "scope": "Inference from the 19 late starts among 74 bookings alone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P002 explicitly states that the aggregate does not establish persistence."
    }
  },
  "signal_basis": {
    "component_id": "C003.signal_basis",
    "value": "An aggregate count of 19 late starts among 74 bookings, without a temporal pattern supplied by that count.",
    "scope": "The reported aggregate alone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P002 supplies the count and explicitly distinguishes an aggregate problem from its temporal character."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C003.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No conditional empirical relation is needed for this supported claim."
    }
  },
  "rationale": "The same aggregate can result from late starts recurring throughout the observation period or clustering in a brief disruption. The count alone therefore does not establish persistence.",
  "uncertainty": "Whether the problem actually persists remains unresolved by the aggregate; this does not undermine the claim about its evidential limits.",
  "anomalies": []
}
